using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

var bingKey = Environment.GetEnvironmentVariable("BING_SEARCH_KEY"); // optional

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptUser("Enter a research topic");

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Notebook (shared state for the note-taking tool) ---
var notebook = new Notebook();

// --- Build the chat client with automatic tool invocation ---
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient("gpt-4o")
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()          // auto-invoke tools
    .Build();

// --- Register tools ---
var searchTool = bingKey is not null
    ? AIFunctionFactory.Create(
          ([Description("The search query")] string query) =>
              BingSearch(query, bingKey),
          "web_search",
          "Search the web for information on a topic. Returns a list of results with titles, URLs, and snippets.")
    : AIFunctionFactory.Create(
          ([Description("The search query")] string query) =>
              SimulatedSearch(query),
          "web_search",
          "Search the web for information on a topic. Returns a list of results with titles, URLs, and snippets.");

var addNoteTool = AIFunctionFactory.Create(
    ([Description("A concise note capturing a key finding")] string note,
     [Description("The source URL or reference for this note")] string source) =>
        notebook.Add(note, source),
    "add_note",
    "Save a research note with its source. Use this to record important findings.");

var getNotesTool = AIFunctionFactory.Create(
    () => notebook.GetAll(),
    "get_notes",
    "Retrieve all notes taken so far. Use before writing the final summary.");

// --- Agent loop ---
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the given topic
        and produce a well-structured summary.

        Workflow:
        1. Search the web 2-3 times with varied queries to gather diverse information.
        2. For each useful finding, call add_note to record it with its source.
        3. Once you have enough material, call get_notes to review everything.
        4. Write a final structured summary with:
           • An overview paragraph
           • Key findings as bullet points
           • A "Sources" section listing URLs

        Be thorough but concise. Cite your sources.
        """),
    new(ChatRole.User, $"Please research the following topic: {topic}")
};

var options = new ChatOptions
{
    Tools = [searchTool, addNoteTool, getNotesTool]
};

Console.WriteLine("Agent is working…\n");

var response = await client.GetResponseAsync(messages, options);

Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("          📋  RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n═══════════════════════════════════════════");
Console.WriteLine($"Notes collected: {notebook.Count}");
Console.WriteLine("═══════════════════════════════════════════");

// --- Helper methods ---

static string PromptUser(string prompt)
{
    Console.Write($"{prompt}: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? throw new InvalidOperationException("No topic provided.")
        : input;
}

static async Task<string> BingSearch(string query, string apiKey)
{
    Console.WriteLine($"  🌐 Searching: \"{query}\"");
    using var http = new HttpClient();
    http.DefaultRequestHeaders.Add("Ocp-Apim-Subscription-Key", apiKey);

    var url = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count=5";
    var json = await http.GetFromJsonAsync<JsonElement>(url);

    var results = new List<object>();
    if (json.TryGetProperty("webPages", out var pages)
        && pages.TryGetProperty("value", out var values))
    {
        foreach (var item in values.EnumerateArray().Take(5))
        {
            results.Add(new
            {
                title   = item.GetProperty("name").GetString(),
                url     = item.GetProperty("url").GetString(),
                snippet = item.GetProperty("snippet").GetString()
            });
        }
    }

    return results.Count > 0
        ? JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true })
        : "No results found.";
}

static Task<string> SimulatedSearch(string query)
{
    Console.WriteLine($"  🌐 Searching (simulated): \"{query}\"");

    // Provide a realistic stub so the agent can still demonstrate the full workflow.
    var results = new[]
    {
        new { title = $"Overview of {query}",           url = $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}", snippet = $"A comprehensive overview covering the key aspects of {query}, including history, current state, and future outlook." },
        new { title = $"Recent developments in {query}", url = $"https://example.com/news/{Uri.EscapeDataString(query)}",      snippet = $"Recent breakthroughs and trends in {query} are reshaping the field, with notable advances in efficiency and adoption." },
        new { title = $"{query} - Expert Analysis",     url = $"https://example.com/analysis/{Uri.EscapeDataString(query)}",   snippet = $"Experts highlight both the opportunities and challenges surrounding {query}, emphasizing the importance of responsible development." }
    };

    return Task.FromResult(
        JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true }));
}

// --- Notebook class ---

sealed class Notebook
{
    private readonly List<(string Note, string Source)> _notes = [];

    public int Count => _notes.Count;

    public string Add(string note, string source)
    {
        _notes.Add((note, source));
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        return $"Note #{_notes.Count} saved.";
    }

    public string GetAll()
    {
        if (_notes.Count == 0) return "No notes recorded yet.";

        return string.Join('\n', _notes.Select((n, i) =>
            $"[{i + 1}] {n.Note}\n    Source: {n.Source}"));
    }
}

